local SettingRefBase = require('Game.Setting.SettingRefBase')

---@class EquipQualityVo
local EquipQualityVo = Class("EquipQualityVo", SettingRefBase)
local base = SettingRefBase

local parse_number = parse_number
local parse_string = parse_string

---__int
function EquipQualityVo:__init()
    self.quality = nil
    self.dec = nil
    self.maxNum = nil
    self.starMax = nil
end


---FillVo
---@param row TableML.TableFileRow
function EquipQualityVo:FillVo(row)
    base.FillVo(self, row)
    self.quality = parse_number(row, "qualityLv", 0)
    self.dec = parse_string(row, "dec", "")
    self.maxNum = parse_number(row, "maxNum", 0)   --- 副属性最大条数
    self.starMax = parse_number(row, "starMax", 0)   --- 最大星级
    self.lvMax = parse_number(row, "lvMax", 0)   --- 最大等级

